// Extract selected stack components from the webhook payload
const body = $input.first().json.body;
const jobId = body.jobId;
const cloudProvider   = body.cloudProvider   || null;
const llmProviders    = body.llmProviders    || []; // array
const codingAgents    = body.codingAgents    || []; // array
const securityTools   = body.securityTools   || []; // array
const useCase         = body.useCase         || 'POC';
const customerContext = body.customerContext || '';

// Build one search query per section — these will be embedded in parallel
const sections = [];

if (cloudProvider) {
  sections.push({
    key: 'cloud',
    label: 'Cloud Provider',
    query: `How to connect ${cloudProvider} to Atlas AI Security runtime protection proxy and configure log sources`,
    components: [cloudProvider]
  });
}

if (llmProviders.length > 0) {
  sections.push({
    key: 'llm',
    label: 'LLM Providers',
    query: `Atlas AI Security integration setup for ${llmProviders.join(', ')} — proxy configuration, policy enforcement, runtime guardrails`,
    components: llmProviders
  });
}

if (codingAgents.length > 0) {
  sections.push({
    key: 'coding',
    label: 'Coding Agents',
    query: `Atlas runtime protection for coding agents ${codingAgents.join(', ')} — MCP server setup, tool governance, policy enforcement`,
    components: codingAgents
  });
}

if (securityTools.length > 0) {
  sections.push({
    key: 'security',
    label: 'Security Integrations',
    query: `Atlas integration with ${securityTools.join(', ')} — log source configuration, alert forwarding, enforcement layer`,
    components: securityTools
  });
}

// Always include a summary/overview section
sections.push({
  key: 'overview',
  label: 'Deployment Overview',
  query: `Atlas AI Security deployment architecture overview onboarding setup ${cloudProvider || ''} ${useCase}`,
  components: ['Atlas Overview']
});

return sections.map(s => ({
  json: {
    ...s,
    jobId,
    useCase,
    customerContext,
    cloudProvider,
    llmProviders,
    codingAgents,
    securityTools,
    totalSections: sections.length
  }
}));

// Build Neo4j vector query — filter to integration source chunks only
const embedding = $input.first().json.data[0].embedding;
const sectionKey = $input.first().json.key;

// Map section key to Neo4j section filter for precision
const sectionMap = {
  cloud:    'integration_cloud',
  llm:      'integration_llm',
  coding:   'integration_coding_agent',
  security: 'integration_security',
  overview: null // overview pulls from all integration + platform docs
};
const sectionFilter = sectionMap[sectionKey];

let statement;
if (sectionFilter) {
  statement = `CALL db.index.vector.queryNodes('atlas_chunk_embeddings', 12, $embedding)
    YIELD node AS c, score
    WHERE c.source = 'integration' AND c.section = '${sectionFilter}' AND score > 0.35
    RETURN c.heading AS heading, c.text AS text, c.title AS title, c.section AS section, score
    ORDER BY score DESC
    LIMIT 8`;
} else {
  // Overview: pull from all integration + platform chunks
  statement = `CALL db.index.vector.queryNodes('atlas_chunk_embeddings', 12, $embedding)
    YIELD node AS c, score
    WHERE c.source = 'integration' AND score > 0.35
    RETURN c.heading AS heading, c.text AS text, c.title AS title, c.section AS section, score
    ORDER BY score DESC
    LIMIT 6`;
}

const body = JSON.stringify({
  statements: [{ statement, parameters: { embedding } }]
});

// Pass all section metadata forward
const item = $input.first().json;
return [{ json: { requestBody: body, ...item, embedding } }];

// Build context string from Neo4j results and generate this section
const item = $input.first();
const results = item.json.results?.[0]?.data || [];

const chunks = results.map(row => {
  const cols = row.row;
  return { heading: cols[0], text: cols[1], title: cols[2], section: cols[3], score: cols[4] };
});

// Deduplicate by heading+title
const seen = new Set();
const unique = chunks.filter(c => {
  const k = `${c.title}::${c.heading}`;
  if (seen.has(k)) return false;
  seen.add(k);
  return true;
});

const context = unique.length > 0
  ? unique.map(c => `### ${c.title} — ${c.heading}\n${c.text}`).join('\n\n---\n\n')
  : '(No specific documentation found for this component — use general Atlas knowledge)';

const sectionKey   = item.json.key;
const sectionLabel = item.json.label;
const components   = item.json.components || [];
const useCase      = item.json.useCase;
const customerContext = item.json.customerContext;
const cloudProvider   = item.json.cloudProvider;
const llmProviders    = item.json.llmProviders;
const codingAgents    = item.json.codingAgents;
const securityTools   = item.json.securityTools;
const jobId           = item.json.jobId;
const totalSections   = item.json.totalSections;

return [{
  json: {
    sectionKey,
    sectionLabel,
    components,
    context,
    useCase,
    customerContext,
    cloudProvider,
    llmProviders,
    codingAgents,
    securityTools,
    jobId,
    totalSections,
    chunkCount: unique.length
  }
}];

