// Parse generated section and pass forward cleanly
const raw = $input.first().json.content[0].text;
const cleaned = raw.replace(/^```json\n?/, '').replace(/\n?```$/, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  // Claude returned raw markdown — wrap it
  parsed = {
    sectionKey: $input.first().json.key || 'unknown',
    sectionLabel: $input.first().json.label || 'Section',
    content: raw
  };
}

return [{ json: parsed }];

// Merge all sections into a single ordered playbook
const items = $input.first().json.data;

// Define desired section order
const ORDER = ['overview', 'cloud', 'llm', 'coding', 'security'];

const sorted = [...items].sort((a, b) => {
  const ai = ORDER.indexOf(a.sectionKey);
  const bi = ORDER.indexOf(b.sectionKey);
  return (ai === -1 ? 99 : ai) - (bi === -1 ? 99 : bi);
});

// Get jobId from Webhook
const jobId = $('Webhook').first().json.body.jobId;
const body  = $('Webhook').first().json.body;

// Build full playbook markdown
const header = [
  '# Atlas Integration Playbook',
  '',
  '**Generated for:**',
  body.cloudProvider   ? `- Cloud Provider: ${body.cloudProvider}` : '',
  body.llmProviders?.length   ? `- LLM Providers: ${body.llmProviders.join(', ')}` : '',
  body.codingAgents?.length   ? `- Coding Agents: ${body.codingAgents.join(', ')}` : '',
  body.securityTools?.length  ? `- Security Integrations: ${body.securityTools.join(', ')}` : '',
  `- Use Case: ${body.useCase || 'POC'}`,
  body.customerContext ? `- Context: ${body.customerContext}` : '',
  '',
  '---',
  ''
].filter(l => l !== undefined && !(l === '' && false)).join('\n');

const sections = sorted
  .filter(s => s && s.content)
  .map(s => s.content)
  .join('\n\n---\n\n');

const playbook = header + sections;

// Write to Upstash KV
const kvValue = JSON.stringify({ status: 'done', playbook });
const kvBody  = JSON.stringify([['SET', 'playbook:' + jobId, kvValue, 'EX', '7200']]);

return [{ json: { playbook, jobId, kvBody } }];
